(* ::Section::*)(*1. Utilities:points->graph*)ClearAll[distanceMatrixRadius,makeGeometricGraph];

distanceMatrixRadius[pts_,k_:8,factor_:1.15]:=Module[{dm,kdist},dm=DistanceMatrix[pts];
kdist=Table[Sort[Delete[dm[[i]],i]][[Min[k,Length[pts]-1]]],{i,Length[pts]}];
factor Median[kdist]];

makeGeometricGraph[pts_,eps_]:=Module[{n,edges},n=Length[pts];
edges=DeleteDuplicates[Sort/@Flatten[Table[If[i<j&&Norm[pts[[i]]-pts[[j]]]<=eps,{{i,j}},{}],{i,n},{j,i+1,n}],2]];
Graph[Range[n],UndirectedEdge@@@edges,VertexCoordinates->Thread[Range[n]->pts],GraphLayout->{"Dimension"->3},VertexSize->Tiny,EdgeStyle->Directive[Gray,Opacity[0.25]]]];

(* ::Section::*)(*2. Shortest-path count estimator*)ClearAll[shortestPathCountsFrom,cubicMeanDeviation,pathAnisotropyEstimator];

shortestPathCountsFrom[g_Graph,source_]:=Module[{verts,adj,dist,counts,frontier,next,d,nb},verts=VertexList[g];
adj=AssociationThread[verts,(AdjacencyList[g,#]&)/@verts];
dist=<|source->0|>;
counts=<|source->1|>;
frontier={source};
d=0;
While[frontier=!={},d++;
next={};
Do[Do[If[!KeyExistsQ[dist,nb],dist[nb]=d;
counts[nb]=counts[u];
AppendTo[next,nb],If[dist[nb]===d,counts[nb]=counts[nb]+counts[u]]],{nb,adj[u]}],{u,frontier}];
frontier=DeleteDuplicates[next];];
<|"Distances"->dist,"Counts"->counts|>];

cubicMeanDeviation[x_List]:=Module[{m},If[Length[x]<=1,Missing["NotEnoughBoundaryPoints"],m=Mean[x];
Mean[Abs[x-m]^3]^(1/3)]];

pathAnisotropyEstimator[g_Graph,source_,radius_Integer]:=Module[{res,dist,counts,shell,pathCounts,oldCMD,normCMD,logCMD},res=shortestPathCountsFrom[g,source];
dist=res["Distances"];
counts=res["Counts"];
shell=Select[Keys[dist],dist[#]==radius&];
If[Length[shell]<=2,Return[<|"Vertex"->source,"Radius"->radius,"ShellSize"->Length[shell],"OldCMD"->Missing["TooSmallShell"],"NormalizedCMD"->Missing["TooSmallShell"],"LogCMD"->Missing["TooSmallShell"]|>]];
pathCounts=counts/@shell;
oldCMD=cubicMeanDeviation[pathCounts]/radius;
normCMD=cubicMeanDeviation[pathCounts]/(Mean[pathCounts]+10^-12);
logCMD=cubicMeanDeviation[Log[pathCounts+10^-12]];
<|"Vertex"->source,"Radius"->radius,"ShellSize"->Length[shell],"MeanPathCount"->Mean[pathCounts],"OldCMD"->oldCMD,"NormalizedCMD"->normCMD,"LogCMD"->logCMD|>];

