GraphicsRow[{plotDataset2D[flat500,"Flat control"],plotDataset3D[hyp500,"Hyperboloid"],plotDataset3D[flamm500,"Flamm / Schwarzschild"]},ImageSize->Large]

(*Replacement for RankData*)ClearAll[rankData];

rankData[x_List]:=Module[{ord,sortedPairs,groups,ranks,pos,len,inds},ord=Ordering[x];
sortedPairs=Transpose[{ord,x[[ord]]}];
groups=Split[sortedPairs,#1[[2]]==#2[[2]]&];
ranks=ConstantArray[0.,Length[x]];
pos=1;
Do[inds=group[[All,1]];
len=Length[group];
(*average rank for ties*)ranks[[inds]]=Mean[Range[pos,pos+len-1]];
pos=pos+len;,{group,groups}];
ranks]

(* ::Section::*)(*Fast radius scan:compute BFS once per vertex*)ClearAll[precomputeAdjacency,shortestPathCountsFromAdj,estimatorFromBFS,evaluateDatasetAllRadii,fastRadiusScan,spearmanCorr];

precomputeAdjacency[g_Graph]:=Module[{verts},verts=VertexList[g];
AssociationThread[verts,(AdjacencyList[g,#]&)/@verts]];

shortestPathCountsFromAdj[adj_Association,source_,maxRadius_Integer]:=Module[{dist,counts,frontier,next,d},dist=<|source->0|>;
counts=<|source->1|>;
frontier={source};
d=0;
While[frontier=!={}&&d<maxRadius,d++;
next={};
Scan[Function[u,Scan[Function[nb,If[!KeyExistsQ[dist,nb],AssociateTo[dist,nb->d];
AssociateTo[counts,nb->Lookup[counts,u,0]];
next=Append[next,nb],If[Lookup[dist,nb,Infinity]===d,AssociateTo[counts,nb->Lookup[counts,nb,0]+Lookup[counts,u,0]]]]],Lookup[adj,u,{}]]],frontier];
frontier=DeleteDuplicates[next];];
<|"Distances"->dist,"Counts"->counts|>];

estimatorFromBFS[source_,radius_Integer,bfs_Association]:=Module[{dist,counts,shell,pathCounts,oldCMD,normCMD,logCMD},dist=bfs["Distances"];
counts=bfs["Counts"];
shell=Keys@Select[dist,#==radius&];
If[Length[shell]<=2,Return[<|"Vertex"->source,"Radius"->radius,"ShellSize"->Length[shell],"MeanPathCount"->Missing["TooSmallShell"],"OldCMD"->Missing["TooSmallShell"],"NormalizedCMD"->Missing["TooSmallShell"],"LogCMD"->Missing["TooSmallShell"]|>]];
pathCounts=Lookup[counts,shell,0];
oldCMD=cubicMeanDeviation[pathCounts]/radius;
normCMD=cubicMeanDeviation[pathCounts]/(Mean[pathCounts]+10^-12);
logCMD=cubicMeanDeviation[Log[pathCounts+10^-12]];
<|"Vertex"->source,"Radius"->radius,"ShellSize"->Length[shell],"MeanPathCount"->Mean[pathCounts],"OldCMD"->oldCMD,"NormalizedCMD"->normCMD,"LogCMD"->logCMD|>];

evaluateDatasetAllRadii[dataset_Association,radii_List]:=Module[{g,verts,target,targetAssoc,adj,maxRadius,rows},g=dataset["Graph"];
verts=VertexList[g];
target=dataset["TargetK"];
targetAssoc=AssociationThread[Range[Length[target]],target];
adj=precomputeAdjacency[g];
maxRadius=Max[radii];
rows=Flatten[Map[Function[v,Module[{bfs},bfs=shortestPathCountsFromAdj[adj,v,maxRadius];
Join[estimatorFromBFS[v,#,bfs],<|"TargetK"->Lookup[targetAssoc,v,Missing["NoTarget"]],"Type"->dataset["Type"],"N"->dataset["N"]|>]&/@radii]],verts],1];
Dataset[rows]];

spearmanCorr[x_,y_]:=Correlation[rankData[N[x]],rankData[N[y]]];

fastRadiusScan[dataset_Association,radii_List,estimatorName_:"LogCMD"]:=Module[{ds,rows,sub,pairs},ds=evaluateDatasetAllRadii[dataset,radii];
rows=Normal[ds];
Dataset[Table[sub=Select[rows,#["Radius"]==rad&&NumericQ[Lookup[#,"TargetK"]]&&NumericQ[Lookup[#,estimatorName]]&];
pairs=N[({#["TargetK"],#[estimatorName]}&)/@sub];
If[Length[pairs]<5,<|"Radius"->rad,"Rows"->Length[pairs],"Pearson"->Missing["TooFewRows"],"Spearman"->Missing["TooFewRows"]|>,<|"Radius"->rad,"Rows"->Length[pairs],"Pearson"->NumberForm[N@Correlation[pairs[[All,1]],pairs[[All,2]]],{5,3}],"Spearman"->NumberForm[N@spearmanCorr[pairs[[All,1]],pairs[[All,2]]],{5,3}]|>],{rad,radii}]]];

ClearAll[oneSeedRadiusScan,multiSeedRadiusScan];

oneSeedRadiusScan[n_,seed_,radii_List,k_Integer:14]:=Module[{data,scan},SeedRandom[seed];
data=buildFlammDataset[n,1/2,k];
scan=Normal[fastRadiusScan[data,radii,"LogCMD"]];
Map[Join[#,<|"Seed"->seed,"N"->n,"k"->k|>]&,scan]];

multiSeedRadiusScan[n_,seeds_List,radii_List,k_Integer:14]:=Dataset[Flatten[oneSeedRadiusScan[n,#,radii,k]&/@seeds,1]];

ClearAll[summarizeSeedScan];

summarizeSeedScan[scan_Dataset]:=Module[{rows,grouped},rows=Normal[scan];
grouped=GroupBy[rows,#Radius&];
Dataset[KeyValueMap[Function[{rad,vals},<|"Radius"->rad,"MeanPearson"->Mean[ToExpression/@ToString/@vals[[All,"Pearson"]]],"MeanSpearman"->Mean[ToExpression/@ToString/@vals[[All,"Spearman"]]],"StdSpearman"->StandardDeviation[ToExpression/@ToString/@vals[[All,"Spearman"]]]|>],grouped]]];

summarizeSeedScan[scan500]

scan200=multiSeedRadiusScan[200,Range[1,10],Range[3,4],12];

scan500=multiSeedRadiusScan[500,Range[1,10],Range[3,4],14];

scan1000=multiSeedRadiusScan[1000,Range[1,5],Range[3,4],16];

summary200=summarizeSeedScan[scan200];
summary500=summarizeSeedScan[scan500];
summary1000=summarizeSeedScan[scan1000];

(* ::Section::*)(*Radial binning for Flamm/Schwarzschild comparison*)ClearAll[binnedFlammComparison];

binnedFlammComparison[dataset_Association,ds_Dataset,estimatorName_:"LogCMD",nbins_Integer:12]:=Module[{rows,rs,rAssoc,joined,rmin,rmax,binEdges,binned},rows=cleanRows[ds,estimatorName];
If[!KeyExistsQ[dataset,"r"],Return["This dataset does not contain radial coordinates under key \\"r\\"."]];
rs=dataset["r"];
rAssoc=AssociationThread[Range[Length[rs]],rs];
joined=Map[Join[#,<|"r"->Lookup[rAssoc,#["Vertex"],Missing["NoR"]]|>]&,rows];
joined=Select[joined,NumericQ[#["r"]]&&NumericQ[#["TargetK"]]&&NumericQ[#[estimatorName]]&];
rmin=Min[Map[#["r"]&,joined]];
rmax=Max[Map[#["r"]&,joined]];
binEdges=Subdivide[rmin,rmax,nbins];
binned=Table[Module[{sub},sub=Select[joined,binEdges[[i]]<=#["r"]<binEdges[[i+1]]&];
If[Length[sub]<5,Nothing,<|"Bin"->i,"rMin"->binEdges[[i]],"rMax"->binEdges[[i+1]],"rMean"->Mean[Map[#["r"]&,sub]],"KMean"->Mean[Map[#["TargetK"]&,sub]],"EstimatorMean"->Mean[Map[#[estimatorName]&,sub]],"EstimatorStd"->StandardDeviation[Map[#[estimatorName]&,sub]],"Count"->Length[sub]|>]],{i,Length[binEdges]-1}];
Dataset[binned]];

