validRealNumberQ[x_]:=Module[{y=Quiet[N[x]]},NumberQ[y]&&FreeQ[y,Indeterminate|ComplexInfinity|DirectedInfinity[_]]&&TrueQ[Im[y]==0]];

rowsWithRAndEstimator[data_,res_,estimator_]:=Module[{rawRows,rvals,rows},rawRows=Normal[res];
rvals=data["r"];
rows=Reap[Do[Module[{v=getRowValue[row,"Vertex"],e=Quiet[N[getRowValue[row,estimator]]]},If[IntegerQ[v]&&1<=v<=Length[rvals]&&validRealNumberQ[e],Sow[<|"Vertex"->v,"r"->N[rvals[[v]]],"Estimator"->N[e]|>]]],{row,rawRows}]][[2]];
