commonRadialBinnedComparison[data1_,res1_,data2_,res2_,estimator_:"LogCMD",nbins_:12]:=Module[{rows1,rows2,rmin,rmax,binEdges,assignBin,addBins,grouped1,grouped2,commonBins},rows1=rowsWithRAndEstimator[data1,res1,estimator];
